import { NextResponse } from "next/server";
import { createClient } from "@supabase/supabase-js";

const supabaseAdmin = createClient(
  process.env.NEXT_PUBLIC_SUPABASE_URL!,
  process.env.SUPABASE_SERVICE_ROLE_KEY!
);

export async function POST(req: Request) {
  try {
    const authHeader = req.headers.get("authorization");
    let userId = null;

    if (authHeader) {
      const jwtToken = authHeader.replace("Bearer ", "").trim();
      const { data } = await supabaseAdmin.auth.getUser(jwtToken);
      if (data?.user) userId = data.user.id;
    }

    const { token, equity, name, role, skillRole } = await req.json();

    if (!token) {
      return NextResponse.json({ error: "Token is required" }, { status: 400 });
    }

    // 🔍 Fetch invite
    const { data: invite } = await supabaseAdmin
      .from("team_invitations")
      .select("*")
      .eq("token", token)
      .maybeSingle();

    if (!invite) {
      return NextResponse.json({ error: "Invalid link" }, { status: 404 });
    }

    if (invite.used) {
      return NextResponse.json({ error: "Already used" }, { status: 400 });
    }

    if (invite.expires_at && new Date(invite.expires_at) < new Date()) {
      return NextResponse.json({ error: "Expired link" }, { status: 400 });
    }

    // ✅ FIX 1: NAME FALLBACK
    const finalName =
      name?.trim() ||
      invite.email?.split("@")[0] ||
      "User";

    // ✅ FIX 2: ROLE SAFE
    const validRoles = ["Member", "Admin", "Leader"];
    const safeRole = validRoles.includes(role) ? role : "Member";

    // ✅ FIX 3: SKILLS ARRAY SAFE
    const skillsArray =
      typeof skillRole === "string"
        ? skillRole
            .split(",")
            .map((s: string) => s.trim().toLowerCase())
            .filter(Boolean)
        : [];

    // ✅ FIX 4: DUPLICATE CHECK
    const { data: existing } = await supabaseAdmin
      .from("team_members")
      .select("id")
      .eq("team_id", invite.team_id)
      .eq("email", invite.email)
      .maybeSingle();

    if (existing) {
      return NextResponse.json({
        success: true,
        message: "Already joined",
      });
    }

    // ✅ FINAL INSERT
    const insertPayload: any = {
      team_id: invite.team_id,
      project_id: invite.project_id,
      role: safeRole,
      skill_role: skillsArray,
      equity: Number(equity) || 0,
      finalized_equity: 0,
      name: finalName,
      email: invite.email,
    };

    if (userId) insertPayload.user_id = userId;

    console.log("🚀 FINAL INSERT:", insertPayload);

    const { error } = await supabaseAdmin
      .from("team_members")
      .insert(insertPayload);

    if (error) {
      console.error("❌ INSERT ERROR:", error);
      return NextResponse.json({ error: error.message }, { status: 500 });
    }

    // ✅ UPDATE INVITE (NO DELETE)
    await supabaseAdmin
      .from("team_invitations")
      .update({ used: true, status: "accepted" })
      .eq("token", token);

    return NextResponse.json({
      success: true,
      message: "Joined successfully",
    });

  } catch (err: any) {
    console.error("🔥 ERROR:", err);
    return NextResponse.json(
      { error: "Internal Server Error" },
      { status: 500 }
    );
  }
}